-- Migration 044: quinta tornata di contenuti News (12 articoli), con date
-- di pubblicazione che proseguono la cadenza della migration 027 (circa un
-- articolo ogni 1,75 giorni) dal 22/08 al 10/09/2026, e categorie a
-- rotazione fissa mutui -> investimenti -> budget -> pianificazione.
-- Argomenti scelti su query di ricerca non ancora coperte (TAN/TAEG,
-- Euribor/IRS, detrazione interessi, BTP, ETF monetari, PAC o PIC, budget
-- familiare, spese fisse/variabili, acquisti d'impulso, TFR, soldi per età,
-- arrivo di un figlio), con link interni ad articoli esistenti e calcolatori.
-- updated_at = published_at per lo stesso motivo della migration 028
-- (lastmod della sitemap). Solo classi già nella safelist di
-- build/tailwind.config.js: nessun rebuild di site.css necessario.
-- Vedi 021_news_articles.sql per lo schema.

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at, updated_at)
VALUES
(
    'tan-e-taeg-mutuo-differenza',
    'TAN e TAEG del mutuo: qual è la differenza e quale guardare per confrontare le offerte',
    'Il TAN dice quanto costa il denaro, il TAEG quanto costa davvero il mutuo. Confondere i due numeri è il modo più rapido per scegliere l''offerta sbagliata.',
    'Differenza tra TAN e TAEG del mutuo spiegata in modo semplice: cosa include ciascun tasso e quale usare per confrontare le offerte delle banche.',
    'mutui',
    '🔢',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando si confrontano due offerte di mutuo, il primo numero che salta all''occhio è quasi sempre il tasso pubblicizzato. Ma nei documenti della banca i tassi sono due, <strong>TAN</strong> e <strong>TAEG</strong>, e misurano cose diverse. Capire la differenza evita di scegliere un mutuo che sembra più economico solo perché sposta parte del costo altrove.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è il TAN</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>TAN</strong> (Tasso Annuo Nominale) è il tasso di interesse puro applicato al capitale prestato. È il numero che, insieme a importo e durata, determina la rata: è quello che usa il piano di <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento alla francese</a> per dividere ogni rata tra quota interessi e quota capitale.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il TAN però non dice nulla di tutto quello che paghi oltre agli interessi: spese di istruttoria, perizia, incasso rata, assicurazioni obbligatorie. Due mutui con lo stesso TAN possono avere un costo complessivo molto diverso.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è il TAEG</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>TAEG</strong> (Tasso Annuo Effettivo Globale) esprime in percentuale annua il costo totale del finanziamento: interessi più le spese obbligatorie legate al mutuo. È pensato proprio per rendere confrontabili offerte costruite in modo diverso, ed è per questo che la banca è tenuta a indicarlo nel PIES, il Prospetto Informativo Europeo Standardizzato che ricevi prima di firmare.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Cosa entra di solito nel TAEG</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Interessi</strong> calcolati al TAN.</li><li><strong>Spese di istruttoria</strong> della pratica.</li><li><strong>Perizia</strong> dell''immobile.</li><li><strong>Spese di incasso rata</strong>, se previste.</li><li><strong>Assicurazioni richieste</strong> come condizione per ottenere il mutuo.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Restano invece fuori alcune spese che non dipendono dalla banca, come l''onorario del notaio: per avere il quadro completo dell''acquisto vanno aggiunte a parte, come spieghiamo nella guida alle <a href="/news/spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa" class="text-accent hover:underline font-medium">spese accessorie del mutuo</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quale tasso guardare per scegliere</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per <strong>confrontare offerte diverse</strong> il numero giusto è il TAEG: un mutuo con TAN più basso ma spese alte può avere un TAEG più alto di un concorrente con TAN leggermente superiore e spese azzerate. Il TAN resta utile per un''altra domanda, cioè quanto pagherai di rata ogni mese.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Attenzione a confrontare TAEG omogenei: stesso importo, stessa durata e stesso tipo di tasso. Il TAEG di un mutuo variabile è calcolato sui parametri di oggi e cambierà con l''andamento dell''<a href="/news/euribor-irs-mutuo-cosa-sono" class="text-accent hover:underline font-medium">Euribor</a>, mentre quello di un fisso resta valido per tutta la durata.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Una differenza ampia è un campanello d''allarme</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se tra TAN e TAEG c''è una distanza molto più ampia rispetto alle altre offerte che stai valutando, quasi sempre ci sono spese o polizze che pesano più del normale. Vale la pena chiedere il dettaglio voce per voce: alcune spese sono negoziabili, e le polizze facoltative non possono essere imposte come condizione.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una volta acceso il mutuo, su <a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi inserirne TAN e durata e vedere il piano di ammortamento completo, con la quota di interessi e di capitale di ogni singola rata.</p>',
    'pubblicato',
    '2026-08-22 09:00:00',
    '2026-08-22 09:00:00'
),
(
    'btp-titoli-di-stato-come-funzionano',
    'BTP e titoli di Stato: come funzionano, quanto rendono e quali rischi hanno',
    'Cedole, prezzo, scadenza e tassazione agevolata: tutto quello che serve sapere sui BTP prima di comprarne uno, e perché il loro prezzo si muove anche se lo Stato paga sempre.',
    'Come funzionano i BTP e i titoli di Stato italiani: cedole, rendimento a scadenza, rischio tasso, tassazione al 12,5% e differenze con i BOT.',
    'investimenti',
    '🇮🇹',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">I titoli di Stato sono spesso il primo investimento a cui pensano i risparmiatori italiani, e per buone ragioni: sono semplici da capire, pagano interessi regolari e godono di una tassazione agevolata. Ma "semplici" non significa "senza rischi", e conviene sapere cosa succede tra l''acquisto e la scadenza.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è un BTP</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un <strong>BTP</strong> (Buono del Tesoro Poliennale) è un prestito che fai allo Stato italiano. In cambio ricevi una <strong>cedola</strong>, cioè un interesse pagato ogni sei mesi, e alla scadenza ti viene restituito il valore nominale. Le durate vanno da pochi anni fino a trenta e oltre.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Accanto ai BTP classici esistono i <strong>BOT</strong>, titoli a breve termine (fino a un anno) che non pagano cedole: il guadagno è la differenza tra il prezzo di acquisto, inferiore a 100, e il rimborso a 100. Ci sono poi emissioni dedicate ai risparmiatori, con caratteristiche specifiche come premi fedeltà o indicizzazione all''inflazione.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché il prezzo di un BTP cambia</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dopo l''emissione i titoli di Stato si comprano e si vendono in Borsa, e il loro prezzo varia. Il motivo principale sono i <strong>tassi di interesse</strong>: se i nuovi titoli vengono emessi con cedole più alte, quelli vecchi con cedole più basse diventano meno appetibili e il loro prezzo scende, e viceversa.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più lunga è la scadenza, più il prezzo reagisce ai tassi: un BTP a trent''anni può perdere molto valore in un periodo di rialzo dei tassi, anche se lo Stato continua a pagare regolarmente. Se lo tieni fino a scadenza ricevi comunque il valore nominale; il rischio diventa concreto se devi vendere prima.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">I rischi da conoscere</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Rischio tasso</strong>: il prezzo scende quando i tassi salgono, tanto più quanto è lunga la scadenza.</li><li><strong>Rischio emittente</strong>: legato alla solidità dei conti pubblici, che si riflette nello spread rispetto ai titoli tedeschi.</li><li><strong>Rischio inflazione</strong>: una cedola fissa può valere meno in termini reali se i prezzi corrono, come spieghiamo nell''articolo sull''<a href="/news/inflazione-potere-acquisto-perche-il-capitale-deve-crescere" class="text-accent hover:underline font-medium">inflazione</a>.</li><li><strong>Rischio di concentrazione</strong>: mettere tutto su un solo emittente va contro il principio della <a href="/news/diversificazione-portafoglio-cosa-significa-davvero" class="text-accent hover:underline font-medium">diversificazione</a>.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quanto rende davvero un BTP</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il dato da guardare non è la cedola ma il <strong>rendimento a scadenza</strong>, che tiene conto anche del prezzo a cui compri. Un BTP con cedola del 2% comprato a 90 rende di più di quanto dica la cedola, perché a scadenza ti verranno restituiti 100.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La tassazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Cedole e plusvalenze sui titoli di Stato italiani, e su quelli dei Paesi in white list, sono tassate al <strong>12,5%</strong> invece del 26% applicato alla maggior parte degli altri strumenti. Resta dovuta l''imposta di bollo dello 0,2% annuo sul valore detenuto. Il quadro completo è nella nostra guida alla <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">tassazione degli investimenti</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi registrare i tuoi titoli di Stato insieme al resto del portafoglio e seguirne il valore aggiornato.</p>',
    'pubblicato',
    '2026-08-23 09:00:00',
    '2026-08-23 09:00:00'
),
(
    'budget-familiare-mensile-come-farlo',
    'Budget familiare mensile: come farlo in 5 passi e mantenerlo nel tempo',
    'Un budget familiare non è un elenco di divieti, ma una fotografia di dove vanno i soldi e di dove vorresti che andassero. Ecco come costruirlo partendo dai dati reali.',
    'Come fare un budget familiare mensile in 5 passi: entrate, spese fisse e variabili, obiettivi di risparmio e revisione periodica, con esempi pratici.',
    'budget',
    '👨‍👩‍👧',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molte famiglie arrivano a fine mese con la sensazione di non sapere dove siano finiti i soldi. Il budget familiare serve proprio a questo: non a vietare spese, ma a renderle visibili, così da poter decidere invece di subire. Ecco un metodo in cinque passi che funziona anche se non hai mai tenuto un bilancio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">1. Parti dalle entrate nette reali</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Scrivi quanto entra davvero ogni mese in casa: stipendi netti, pensioni, eventuali entrate extra ricorrenti. Se una parte del reddito è variabile, usa come base la cifra più bassa degli ultimi mesi, non la media: è meglio essere sorpresi in positivo.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ricorda le mensilità aggiuntive come tredicesima e quattordicesima: non vanno spalmate nel budget mensile, ma conviene decidere in anticipo a cosa destinarle.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">2. Ricostruisci le spese degli ultimi tre mesi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima di decidere quanto spendere, devi sapere quanto spendi. Riprendi estratti conto e ricevute degli ultimi tre mesi e raggruppa le uscite per categoria: casa, spesa alimentare, trasporti, bollette, salute, figli, tempo libero. Tre mesi bastano a far emergere le abitudini senza essere falsati da un mese anomalo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">3. Separa spese fisse e spese variabili</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le spese fisse (affitto o <a href="/mutui.php" class="text-accent hover:underline font-medium">rata del mutuo</a>, assicurazioni, abbonamenti) cambiano poco da un mese all''altro; quelle variabili (spesa, ristoranti, carburante) sono dove si gioca la partita. Ne parliamo in dettaglio nella guida a <a href="/news/spese-fisse-e-variabili-differenza" class="text-accent hover:underline font-medium">spese fisse e spese variabili</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">4. Assegna un tetto a ogni categoria</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ora puoi dare a ogni categoria variabile un limite mensile realistico, partendo da quanto hai speso davvero e limando dove ti sembra di esagerare. Se preferisci un punto di partenza semplice, la <a href="/news/regola-50-30-20-vs-budget-per-categoria" class="text-accent hover:underline font-medium">regola 50/30/20</a> divide il reddito in necessità, desideri e risparmio.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio va trattato come una voce di spesa, da mettere da parte a inizio mese e non con quello che avanza. Prima di tutto conviene costruire un <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">5. Rivedi il budget ogni mese</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un budget non si scrive una volta per sempre. A fine mese confronta il previsto con lo speso: dove hai sforato, chiediti se il limite era irrealistico o se è stata una scelta occasionale. Dopo due o tre revisioni il budget smette di essere un esercizio teorico e diventa uno strumento di decisione.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Gli errori più comuni</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Dimenticare le spese annuali</strong> come bollo auto, assicurazioni e manutenzioni: dividile per dodici e accantonale ogni mese.</li><li><strong>Fissare limiti troppo stretti</strong> che vengono abbandonati dopo poche settimane.</li><li><strong>Non coinvolgere tutta la famiglia</strong>: un budget rispettato da una sola persona difficilmente regge.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi impostare un budget per ogni categoria e vedere in tempo reale quanto ti resta, con un avviso quando ti avvicini al limite.</p>',
    'pubblicato',
    '2026-08-25 09:00:00',
    '2026-08-25 09:00:00'
),
(
    'tfr-in-azienda-o-fondo-pensione',
    'TFR in azienda o nel fondo pensione: come scegliere e cosa cambia davvero',
    'Entro sei mesi dall''assunzione devi decidere dove va il tuo TFR. È una scelta che pesa per decenni: ecco come funzionano le due opzioni e cosa considerare.',
    'TFR in azienda o nel fondo pensione? Rivalutazione, tassazione, contributo del datore di lavoro e reversibilità della scelta spiegati in modo chiaro.',
    'pianificazione',
    '🗂️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il TFR, il trattamento di fine rapporto, è una parte della retribuzione che ogni anno viene accantonata e ti viene pagata quando il rapporto di lavoro finisce. Chi viene assunto nel settore privato deve scegliere entro sei mesi se lasciarlo in azienda o destinarlo a un fondo pensione. È una decisione che molti prendono senza pensarci, ma che può valere decine di migliaia di euro a fine carriera.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Se lasci il TFR in azienda</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il TFR lasciato in azienda viene rivalutato ogni anno con un tasso fisso dell''1,5% più il 75% dell''inflazione. È una rivalutazione prevedibile e senza rischi di mercato, che protegge abbastanza bene il potere d''acquisto ma raramente fa crescere il capitale in termini reali.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Al momento della liquidazione il TFR è soggetto a tassazione separata, con un''aliquota legata al tuo reddito medio degli ultimi anni: per redditi medio-alti può essere sensibilmente più alta di quella dei fondi pensione.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Se lo versi nel fondo pensione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nel fondo pensione il TFR viene investito sui mercati, secondo la linea che scegli: più prudente o più orientata alle azioni. Su orizzonti lunghi il rendimento atteso è più alto della rivalutazione in azienda, ma non è garantito e può oscillare nel tempo.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">I vantaggi fiscali e contributivi</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Tassazione finale agevolata</strong>: dal 15% al 9%, scendendo di 0,3 punti per ogni anno di partecipazione oltre il quindicesimo.</li><li><strong>Contributo del datore di lavoro</strong>: nei fondi negoziali di categoria, se versi anche un tuo contributo, spesso l''azienda aggiunge una quota che altrimenti non riceveresti.</li><li><strong>Deducibilità</strong> dei contributi aggiuntivi che versi di tasca tua, entro il limite annuo previsto dalla legge.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Questi elementi, in particolare il contributo del datore, sono spesso decisivi: è denaro in più che con il TFR in azienda andrebbe perso.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La scelta è reversibile solo in una direzione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Puoi lasciare il TFR in azienda e decidere più avanti di spostarlo nel fondo pensione, ma non il contrario: una volta scelto il fondo, il TFR futuro continuerà ad andare lì. Se non scegli nulla entro sei mesi, scatta il silenzio-assenso e il TFR viene versato al fondo negoziale previsto dal tuo contratto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come orientarsi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">In generale il fondo pensione tende a essere più conveniente per chi ha molti anni di lavoro davanti e ha diritto al contributo del datore; chi è vicino alla pensione o vuole la massima prevedibilità può preferire l''azienda. Per capire quanto ti servirà davvero leggi la nostra guida alla <a href="/news/pensione-integrativa-fondo-pensione-quanto-serve" class="text-accent hover:underline font-medium">pensione integrativa</a> e prova il <a href="/calcolatore-pensione.php" class="text-accent hover:underline font-medium">calcolatore pensione</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le regole su anticipazioni e riscatti sono articolate: prima di decidere conviene leggere la nota informativa del fondo e, se hai dubbi, chiedere al tuo CAF o al consulente del lavoro.</p>',
    'pubblicato',
    '2026-08-27 09:00:00',
    '2026-08-27 09:00:00'
),
(
    'euribor-irs-mutuo-cosa-sono',
    'Euribor e IRS: cosa sono e come influenzano la rata del tuo mutuo',
    'Il tasso del tuo mutuo non lo decide solo la banca: dipende da due indici di mercato, l''Euribor per il variabile e l''IRS per il fisso. Ecco come leggerli.',
    'Cosa sono Euribor e IRS (Eurirs), come vengono usati per calcolare il tasso dei mutui variabili e fissi e perché cambiano nel tempo.',
    'mutui',
    '📡',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando una banca ti propone un mutuo, il tasso che vedi è composto da due parti: un <strong>indice di riferimento</strong>, uguale per tutti, e uno <strong>spread</strong>, cioè il margine della banca. Capire gli indici aiuta a leggere le offerte e a interpretare cosa succede alla tua rata quando "i tassi salgono".</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è l''Euribor</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''<strong>Euribor</strong> (Euro Interbank Offered Rate) è il tasso medio a cui le principali banche europee si prestano denaro tra loro. Viene pubblicato ogni giorno lavorativo per diverse scadenze, le più usate nei mutui sono a uno e a tre mesi.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È l''indice di riferimento dei <strong>mutui a tasso variabile</strong>: il tuo tasso è Euribor più spread, e si aggiorna periodicamente seguendo l''andamento dell''indice. L''Euribor si muove soprattutto in base alle decisioni della Banca Centrale Europea sui tassi ufficiali: quando la BCE alza i tassi, l''Euribor sale e con lui la rata del variabile.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è l''IRS</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''<strong>IRS</strong> (Interest Rate Swap), detto anche Eurirs, è l''indice di riferimento dei <strong>mutui a tasso fisso</strong>. Esprime il tasso a cui il mercato è disposto a scambiare un tasso variabile con uno fisso per un certo numero di anni, e per questo incorpora le aspettative sui tassi futuri.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per un mutuo fisso a 25 anni la banca prende come base l''IRS a 25 anni del momento in cui stipuli, ci aggiunge lo spread e quel tasso resta bloccato per tutta la durata. Le variazioni successive dell''IRS non toccano più la tua rata.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché Euribor e IRS possono essere molto diversi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''Euribor fotografa il costo del denaro oggi, l''IRS sintetizza cosa il mercato si aspetta per gli anni a venire. Se i mercati prevedono tassi in calo, l''IRS può essere più basso dell''Euribor, rendendo il fisso più conveniente del variabile già alla partenza; quando ci si aspettano rialzi accade il contrario.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Cosa guardare in un''offerta</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Lo spread</strong>: è la parte che dipende dalla banca ed è quella su cui ha senso confrontare le offerte.</li><li><strong>L''indice usato</strong>: per il variabile, quale Euribor e ogni quanto viene aggiornato.</li><li><strong>Eventuali tetti</strong>: alcuni mutui variabili prevedono un tasso massimo (cap) che limita gli aumenti.</li><li><strong>Il <a href="/news/tan-e-taeg-mutuo-differenza" class="text-accent hover:underline font-medium">TAEG</a></strong>, che include anche le spese e rende le offerte confrontabili.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quale scegliere</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non esiste una risposta valida per tutti: dipende da quanto puoi sopportare un aumento della rata e da quanto pesa la rata sul reddito. Ne parliamo nella guida al <a href="/news/mutuo-tasso-fisso-o-variabile-come-scegliere" class="text-accent hover:underline font-medium">mutuo a tasso fisso o variabile</a>. E se i tassi cambiano molto dopo la firma, la <a href="/news/surroga-mutuo-cosa-e-come-funziona" class="text-accent hover:underline font-medium">surroga</a> permette di trasferire il mutuo a condizioni migliori senza costi.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi simulare come cambierebbe la rata di un mutuo variabile al variare del tasso, per capire in anticipo quanto margine hai nel tuo bilancio.</p>',
    'pubblicato',
    '2026-08-29 09:00:00',
    '2026-08-29 09:00:00'
),
(
    'etf-monetari-o-conto-deposito',
    'ETF monetari o conto deposito: dove parcheggiare la liquidità e cosa cambia',
    'Entrambi servono a far rendere la liquidità con rischi contenuti, ma funzionano in modo diverso: vincoli, tassazione, protezione del capitale e flessibilità a confronto.',
    'ETF monetari o conto deposito per la liquidità? Differenze di rendimento, vincoli, tassazione, garanzie e flessibilità per scegliere lo strumento giusto.',
    'investimenti',
    '🪙',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Chi ha liquidità che non vuole investire in Borsa, ma nemmeno lasciare ferma sul conto corrente, si trova spesso davanti a due alternative: il conto deposito e gli ETF monetari. Rendono in modo simile quando i tassi sono positivi, ma hanno caratteristiche molto diverse.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona un conto deposito</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>conto deposito</strong> è un conto bancario su cui depositi una somma in cambio di un interesse. Può essere <strong>libero</strong>, con soldi prelevabili in qualsiasi momento, oppure <strong>vincolato</strong> per un periodo prestabilito, di solito con un tasso più alto. Il tasso è noto in anticipo: sai esattamente quanto incasserai.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I depositi sono protetti dal Fondo Interbancario di Tutela dei Depositi fino a 100.000 euro per depositante e per banca, in caso di dissesto dell''istituto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona un ETF monetario</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un <strong>ETF monetario</strong> investe in strumenti a brevissimo termine e di alta qualità, oppure replica il tasso interbancario overnight dell''area euro (€STR). Il suo valore cresce quasi ogni giorno, seguendo i tassi a breve: se la BCE li alza il rendimento sale, se li taglia scende.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si compra e si vende in Borsa tramite il tuo intermediario, senza vincoli di durata. Il patrimonio dell''ETF è separato da quello della società che lo gestisce: non c''è la garanzia del fondo interbancario, ma i titoli restano dei sottoscrittori anche se l''emittente fallisce.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le differenze principali</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Rendimento</strong>: fisso e noto nel conto deposito vincolato, variabile giorno per giorno nell''ETF monetario.</li><li><strong>Liquidabilità</strong>: l''ETF si vende in qualsiasi giorno di Borsa; un deposito vincolato può prevedere penali o la perdita degli interessi in caso di svincolo anticipato.</li><li><strong>Costi</strong>: l''ETF ha un <a href="/news/ter-costi-etf-quanto-incidono-sul-rendimento" class="text-accent hover:underline font-medium">TER</a> e le commissioni del broker a ogni operazione; il conto deposito in genere è gratuito.</li><li><strong>Rischio</strong>: entrambi molto contenuti, ma l''ETF può avere oscillazioni minime e, in fasi di tassi negativi, perdere valore.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La tassazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sia gli interessi del conto deposito sia i guadagni degli ETF monetari sono tassati al <strong>26%</strong>, e su entrambi si applica l''imposta di bollo dello 0,2% annuo. C''è però una differenza: i guadagni degli ETF sono redditi di capitale e non possono compensare eventuali minusvalenze accumulate su altri investimenti. Trovi i dettagli nella guida alla <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">tassazione degli investimenti</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quale scegliere</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il conto deposito vincolato è adatto quando sai che non ti serviranno i soldi per un periodo definito e vuoi un rendimento certo. L''ETF monetario è più flessibile, utile se la liquidità potrebbe servirti all''improvviso o se pensi di investirla gradualmente in un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a>. Per il <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a> conta soprattutto la disponibilità immediata.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi tenere traccia sia dei conti con interessi sia degli ETF, e vedere come pesano sul tuo patrimonio complessivo.</p>',
    'pubblicato',
    '2026-08-30 09:00:00',
    '2026-08-30 09:00:00'
),
(
    'spese-fisse-e-variabili-differenza',
    'Spese fisse e spese variabili: come distinguerle e dove si risparmia davvero',
    'Sapere quali spese sono fisse e quali variabili è il primo passo per capire dove intervenire. Ecco come classificarle, con esempi pratici e le voci che sfuggono più spesso.',
    'Differenza tra spese fisse e spese variabili con esempi pratici: come classificarle nel budget, quali ridurre per prime e come gestire le spese annuali.',
    'budget',
    '📌',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando si prova a risparmiare, l''istinto è tagliare un po'' ovunque. Ma le spese non sono tutte uguali: alcune sono difficili da toccare nel breve periodo, altre cambiano ogni settimana in base alle nostre scelte. Distinguere spese fisse e variabili permette di concentrare gli sforzi dove servono.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa sono le spese fisse</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le <strong>spese fisse</strong> hanno un importo uguale o quasi uguale ogni mese, e spesso sono legate a un contratto. Esempi tipici:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Affitto o <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">rata del mutuo</a>.</li><li>Rate di finanziamenti e prestiti.</li><li>Assicurazioni pagate a rate mensili.</li><li>Abbonamenti: telefono, internet, palestra, piattaforme streaming.</li><li>Rette scolastiche o dell''asilo.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si possono ridurre, ma di solito richiedono una decisione una tantum: rinegoziare, cambiare fornitore, disdire. Il vantaggio è che, una volta fatto, il risparmio si ripete ogni mese senza ulteriore fatica.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa sono le spese variabili</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le <strong>spese variabili</strong> cambiano da un mese all''altro in base ai consumi e alle abitudini: spesa alimentare, carburante, ristoranti, abbigliamento, regali, tempo libero. Sono le spese su cui hai più controllo giorno per giorno, ma anche quelle che sfuggono più facilmente, perché sono fatte di tante piccole uscite.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Il caso delle bollette</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Luce, gas e acqua sono a metà strada: sono ricorrenti come una spesa fissa, ma il loro importo dipende dai consumi e dalla stagione. Nel budget conviene trattarle come fisse, usando la media dell''ultimo anno, e controllarle come variabili.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le spese annuali: le grandi dimenticate</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Bollo auto, assicurazione pagata in un''unica soluzione, revisione, TARI, manutenzione della caldaia: sono spese certe che arrivano una o due volte l''anno e mettono in crisi il bilancio del mese in cui cadono. Il metodo più semplice è sommarle, dividere per dodici e accantonare quella cifra ogni mese, come se fosse una spesa fissa.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Dove intervenire per primi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una buona regola è partire dalle <strong>spese fisse</strong>, perché ogni euro risparmiato lì vale dodici volte in un anno senza richiedere rinunce quotidiane. Un controllo degli <a href="/news/abbonamenti-dimenticati-come-scovare-spese-ricorrenti" class="text-accent hover:underline font-medium">abbonamenti dimenticati</a> o una rinegoziazione dell''assicurazione possono valere più di mesi di piccoli sacrifici.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sulle <strong>spese variabili</strong> funziona meglio un limite per categoria, come nel <a href="/news/metodo-delle-buste-budget-digitale" class="text-accent hover:underline font-medium">metodo delle buste</a>: non si vieta nulla, ma si decide in anticipo quanto spendere.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> ogni transazione è legata a una categoria e le spese ricorrenti si registrano da sole, così vedi in ogni momento quanto pesano le une e le altre.</p>',
    'pubblicato',
    '2026-09-01 09:00:00',
    '2026-09-01 09:00:00'
),
(
    'gestire-i-soldi-a-20-30-40-50-anni',
    'Come gestire i soldi a 20, 30, 40 e 50 anni: le priorità per ogni età',
    'Le priorità finanziarie cambiano con l''età: a 20 anni conta costruire abitudini, a 50 proteggere quanto accumulato. Una guida decennio per decennio.',
    'Come gestire i soldi a 20, 30, 40 e 50 anni: priorità finanziarie per ogni età tra risparmio, investimenti, casa, figli e pensione.',
    'pianificazione',
    '🧭',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non esiste un piano finanziario valido per tutta la vita: le entrate, le spese e gli obiettivi cambiano molto da un decennio all''altro. Quello che resta costante sono alcuni principi, da applicare con priorità diverse a seconda della fase in cui ti trovi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">A 20 anni: costruire le abitudini</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il reddito è spesso basso e incerto, ma è il momento in cui il tempo lavora di più a tuo favore. La priorità non è quanto risparmi, ma <strong>abituarti a risparmiare</strong>: anche piccole cifre messe da parte con regolarità contano grazie all''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>.</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Tieni traccia delle spese per capire dove vanno i soldi.</li><li>Costruisci un primo <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>, anche piccolo.</li><li>Evita i debiti al consumo per spese non necessarie.</li><li>Inizia a informarti sugli investimenti con cifre che puoi permetterti di vedere oscillare.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">A 30 anni: le grandi decisioni</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È spesso il decennio delle scelte importanti: casa, convivenza o matrimonio, figli. Il reddito cresce, ma crescono anche gli impegni. Diventa fondamentale avere un <a href="/news/budget-familiare-mensile-come-farlo" class="text-accent hover:underline font-medium">budget familiare</a> chiaro e valutare con attenzione quanto debito puoi sostenere: il <a href="/news/rapporto-debito-reddito-dti-cosa-e" class="text-accent hover:underline font-medium">rapporto debito/reddito</a> è un buon indicatore.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È anche il momento giusto per avviare un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a> e per decidere dove destinare il <a href="/news/tfr-in-azienda-o-fondo-pensione" class="text-accent hover:underline font-medium">TFR</a>, se non l''hai già fatto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">A 40 anni: accelerare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Spesso è la fase con il reddito più alto, ma anche con le spese più alte. Il rischio è che lo stile di vita cresca al ritmo dello stipendio, lasciando invariato il <a href="/news/tasso-di-risparmio-cosa-e-come-calcolarlo" class="text-accent hover:underline font-medium">tasso di risparmio</a>. È il momento di verificare se sei in linea con gli obiettivi di lungo periodo, a partire dalla pensione, e di valutare se <a href="/news/estinzione-anticipata-mutuo-quando-conviene" class="text-accent hover:underline font-medium">estinguere in anticipo il mutuo</a> o investire la differenza.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">A 50 anni: proteggere e preparare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La pensione non è più un concetto astratto. La priorità diventa ridurre gradualmente il rischio del portafoglio, verificare la propria posizione contributiva e stimare quanto servirà davvero. Il <a href="/news/ribilanciamento-portafoglio-cosa-e-perche" class="text-accent hover:underline font-medium">ribilanciamento</a> aiuta a mantenere il livello di rischio adatto all''orizzonte che si accorcia.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il filo conduttore</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">In ogni decennio la misura che conta di più è il <a href="/news/patrimonio-netto-cos-e-perche-seguirlo-nel-tempo" class="text-accent hover:underline font-medium">patrimonio netto</a>: quello che possiedi meno quello che devi. Seguirlo nel tempo dice se stai andando nella direzione giusta molto meglio del solo stipendio. Puoi calcolarlo con il nostro <a href="/calcolatore-patrimonio-netto.php" class="text-accent hover:underline font-medium">calcolatore del patrimonio netto</a> o seguirlo mese per mese su <a href="/analisi.php" class="text-accent hover:underline font-medium">Reflexi</a>.</p>',
    'pubblicato',
    '2026-09-03 09:00:00',
    '2026-09-03 09:00:00'
),
(
    'detrazione-interessi-mutuo-prima-casa',
    'Detrazione degli interessi del mutuo prima casa: come funziona e quanto si recupera',
    'Gli interessi del mutuo per l''abitazione principale danno diritto a una detrazione del 19% nella dichiarazione dei redditi. Ecco requisiti, limiti e spese accessorie detraibili.',
    'Detrazione interessi passivi mutuo prima casa: il 19% fino a 4.000 euro l''anno, requisiti, oneri accessori detraibili e come indicarla nel 730.',
    'mutui',
    '🧾',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Chi ha un mutuo per acquistare la propria abitazione principale può recuperare ogni anno una parte degli interessi pagati, tramite la dichiarazione dei redditi. È uno dei benefici fiscali più diffusi, ma i requisiti sono precisi e vale la pena conoscerli per non perderlo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quanto si recupera</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La detrazione è pari al <strong>19% degli interessi passivi</strong> pagati nell''anno, e degli oneri accessori, calcolata su un importo massimo di <strong>4.000 euro</strong>. Il beneficio massimo è quindi di 760 euro all''anno, che riducono l''IRPEF dovuta e si traducono di solito in un rimborso in busta paga o con la pensione.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il limite riguarda il mutuo, non la persona: se il mutuo è cointestato, ciascun intestatario detrae la propria quota di interessi entro la propria quota del limite. Ricorda che la detrazione riguarda solo gli interessi: la parte di capitale della rata, che vedi nel piano di <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento</a>, non è detraibile.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I requisiti principali</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Il mutuo deve essere stato stipulato per <strong>acquistare l''abitazione principale</strong>, cioè quella in cui tu o i tuoi familiari dimorate abitualmente.</li><li>L''acquisto deve avvenire nell''anno precedente o successivo alla stipula del mutuo.</li><li>Devi adibire l''immobile ad abitazione principale entro un anno dall''acquisto.</li><li>Il mutuo deve essere garantito da ipoteca sull''immobile acquistato.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se smetti di abitare nella casa, ad esempio perché la affitti, in genere perdi il diritto alla detrazione dall''anno successivo, salvo alcune eccezioni come il trasferimento per motivi di lavoro.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Gli oneri accessori detraibili</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Oltre agli interessi, rientrano nel limite di 4.000 euro anche alcune spese legate al mutuo:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Spese di istruttoria e perizia della banca.</li><li>Onorario del notaio per l''atto di mutuo, non quello per la compravendita.</li><li>Imposta sostitutiva sul mutuo.</li><li>Provvigione del mediatore creditizio, se ti sei rivolto a uno.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molte di queste voci sono le stesse che compongono le <a href="/news/spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa" class="text-accent hover:underline font-medium">spese accessorie del mutuo</a>: conservare fatture e ricevute fin dal rogito evita di perdere una parte del beneficio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come richiederla</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ogni anno la banca invia la certificazione degli interessi pagati, che di solito viene già inserita nella dichiarazione precompilata. Nel 730 la detrazione va nella sezione degli oneri detraibili: conviene verificare che l''importo coincida con la certificazione, soprattutto nell''anno della stipula, quando ci sono gli oneri accessori. Dopo una <a href="/news/surroga-mutuo-cosa-e-come-funziona" class="text-accent hover:underline font-medium">surroga</a> la detrazione continua, nei limiti del capitale residuo trasferito.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le regole fiscali hanno molti casi particolari: per situazioni specifiche, come la costruzione o la ristrutturazione della casa, rivolgiti a un CAF o a un commercialista. Per tenere sotto controllo quanto paghi di interessi ogni anno puoi usare la sezione <a href="/mutui.php" class="text-accent hover:underline font-medium">mutui di Reflexi</a>.</p>',
    'pubblicato',
    '2026-09-04 09:00:00',
    '2026-09-04 09:00:00'
),
(
    'pac-o-pic-investire-tutto-subito-o-a-rate',
    'PAC o PIC: meglio investire tutto subito o un po'' alla volta?',
    'Hai una somma da investire: la metti tutta sul mercato oggi o la distribuisci nel tempo? Cosa dicono i dati storici e perché la risposta non è solo matematica.',
    'PAC o PIC, meglio investire tutto subito o a rate? Pro e contro di piano di accumulo e investimento in un''unica soluzione, tra dati storici e psicologia.',
    'investimenti',
    '⏱️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se ricevi un''eredità, un bonus o vendi un immobile, prima o poi ti troverai davanti a una domanda: investo tutto subito o un po'' alla volta? Nel gergo si parla di <strong>PIC</strong> (Piano di Investimento del Capitale, cioè tutto in un''unica soluzione) e di <strong>PAC</strong> (Piano di Accumulo del Capitale, cioè rate periodiche).</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa dicono i dati storici</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su orizzonti lunghi i mercati azionari sono saliti più spesso di quanto siano scesi. Per questo, guardando i dati storici, l''investimento in un''unica soluzione ha battuto il piano di accumulo nella maggior parte dei casi, circa due volte su tre secondo diversi studi: entrare subito significa restare esposti più a lungo alla crescita media del mercato.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il rovescio della medaglia è che in circa un caso su tre il PAC ha fatto meglio, ed è proprio il caso che fa più paura: investire tutto il giorno prima di un forte ribasso.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I vantaggi del PAC</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Riduce il rischio di tempismo</strong>: non punti tutto su un singolo momento del mercato.</li><li><strong>Media il prezzo di acquisto</strong>: compri più quote quando i prezzi sono bassi e meno quando sono alti.</li><li><strong>È più facile da sostenere</strong>: vedere un ribasso su una parte del capitale pesa meno che vederlo su tutto.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quest''ultimo punto è spesso il più importante. Un investimento razionalmente ottimo ma che ti porta a vendere tutto in preda al panico al primo ribasso del 20% è peggiore di uno meno efficiente che riesci a mantenere. Ricorda anche che recuperare una perdita richiede un rialzo più ampio, come spieghiamo nell''articolo sul <a href="/news/recupero-perdite-perche-non-e-simmetrico" class="text-accent hover:underline font-medium">recupero delle perdite</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I vantaggi del PIC</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il PIC è più semplice, sfrutta subito tutto il tempo disponibile e, a parità di altre condizioni, comporta meno commissioni perché fai un solo acquisto. Il denaro che aspetta di essere investito, invece, rende poco: nel frattempo può essere parcheggiato in strumenti di liquidità come gli <a href="/news/etf-monetari-o-conto-deposito" class="text-accent hover:underline font-medium">ETF monetari o un conto deposito</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Una via di mezzo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molti scelgono una soluzione ibrida: investono subito una parte, ad esempio metà, e distribuiscono il resto in un PAC di sei-dodici mesi. Non è la scelta matematicamente ottimale, ma riduce il rimpianto in entrambi gli scenari ed è facile da mantenere.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Qualunque sia la scelta, conta che sia coerente con il tuo orizzonte temporale e con la <a href="/news/diversificazione-portafoglio-cosa-significa-davvero" class="text-accent hover:underline font-medium">diversificazione</a> del portafoglio. Puoi confrontare i due approcci con il <a href="/calcolatore-piano-investimento.php" class="text-accent hover:underline font-medium">calcolatore del piano di investimento</a> e poi seguire l''andamento reale su <a href="/investimenti.php" class="text-accent hover:underline font-medium">Reflexi</a>.</p>',
    'pubblicato',
    '2026-09-06 09:00:00',
    '2026-09-06 09:00:00'
),
(
    'acquisti-impulsivi-come-evitarli',
    'Acquisti d''impulso: perché li facciamo e 7 strategie concrete per evitarli',
    'Gli acquisti d''impulso sono piccoli uno per uno, ma messi insieme possono svuotare il budget. Ecco perché succedono e alcune regole semplici per tenerli sotto controllo.',
    'Come evitare gli acquisti d''impulso: perché compriamo senza pensarci e 7 strategie pratiche, dalla regola delle 48 ore alla lista dei desideri.',
    'budget',
    '🛒',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un paio di scarpe in offerta, un gadget visto sui social, l''aggiunta al carrello "già che ci sono". Gli acquisti d''impulso raramente sono grandi, ma sono frequenti, e alla fine del mese spesso spiegano buona parte della differenza tra quanto pensavi di spendere e quanto hai speso davvero.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché compriamo d''impulso</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non è solo mancanza di forza di volontà. Molti acquisti impulsivi nascono da emozioni come noia, stress o voglia di gratificazione, e sono favoriti da un ambiente pensato per renderli facili: pagamento con un clic, offerte a tempo, notifiche, "ultimi pezzi disponibili". Più è facile comprare, meno ci si ferma a pensare.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">7 strategie concrete</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">1. La regola delle 48 ore</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per ogni acquisto non pianificato sopra una certa cifra, per esempio 50 euro, aspetta 48 ore prima di comprare. Se dopo due giorni lo vuoi ancora, probabilmente è un desiderio vero. Spesso la voglia passa da sola.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">2. La lista dei desideri</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Invece di comprare subito, aggiungi l''oggetto a una lista. Rileggerla dopo qualche settimana è istruttivo: molte voci non ti interesseranno più.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">3. Togli i dati di pagamento salvati</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dover inserire a mano i dati della carta aggiunge un piccolo ostacolo, sufficiente a farti chiedere se ti serve davvero.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">4. Disiscriviti dalle newsletter promozionali</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ogni email di sconto è un invito a comprare qualcosa che non stavi cercando. Meno stimoli, meno tentazioni.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">5. Traduci il prezzo in ore di lavoro</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividi il prezzo per quanto guadagni all''ora: un acquisto da 120 euro può valere un''intera giornata di lavoro, e vista così la decisione cambia.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">6. Dai un budget al superfluo</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Vietarsi tutto non funziona. Meglio una categoria dedicata agli sfizi, con un tetto mensile: dentro quel limite spendi senza sensi di colpa, fuori no. È il principio del <a href="/news/metodo-delle-buste-budget-digitale" class="text-accent hover:underline font-medium">metodo delle buste</a>.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">7. Guarda i numeri a fine mese</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Registrare ogni spesa, anche piccola, rende visibile quanto pesano gli acquisti non pianificati. È uno dei motivi per cui <a href="/news/tracciare-spese-manualmente-vs-collegamento-bancario" class="text-accent hover:underline font-medium">tracciare le spese a mano</a> aumenta la consapevolezza.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il vero obiettivo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non si tratta di non concedersi mai nulla, ma di spendere per ciò che conta davvero per te. Ogni euro non speso d''impulso può andare verso un <a href="/news/obiettivi-risparmio-come-fissarli-e-raggiungerli" class="text-accent hover:underline font-medium">obiettivo di risparmio</a> concreto. Su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi creare una categoria per gli sfizi e vedere a colpo d''occhio quanto ti resta nel mese.</p>',
    'pubblicato',
    '2026-09-08 09:00:00',
    '2026-09-08 09:00:00'
),
(
    'arrivo-di-un-figlio-pianificare-le-spese',
    'Arriva un figlio: come pianificare le spese e adattare il budget familiare',
    'Un figlio cambia le priorità e anche il bilancio di casa. Come prepararsi prima della nascita, quali spese prevedere nei primi anni e come impostare il risparmio per il suo futuro.',
    'Come pianificare le spese per l''arrivo di un figlio: costi dei primi anni, budget familiare, fondo di emergenza, sostegni pubblici e risparmio per il futuro.',
    'pianificazione',
    '🍼',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''arrivo di un figlio è uno dei cambiamenti più grandi nella vita di una famiglia, anche dal punto di vista economico. Le spese aumentano, a volte il reddito cala per il periodo di congedo, e cambiano le priorità di lungo periodo. Prepararsi per tempo rende il passaggio molto più sereno.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Prima della nascita</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I mesi dell''attesa sono il momento ideale per organizzarsi. Tre cose da fare subito:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Rafforzare il fondo di emergenza</strong>: con un figlio gli imprevisti costano di più, e conviene portare il <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a> verso la parte alta della forbice consigliata.</li><li><strong>Stimare l''impatto del congedo</strong>: verifica quanto entrerà durante il congedo di maternità e parentale, che può essere retribuito solo in parte.</li><li><strong>Distinguere il necessario dal superfluo</strong>: molto dell''equipaggiamento per i primi mesi si usa per poco tempo e si trova facilmente usato o in prestito.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le nuove voci del budget</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nel <a href="/news/budget-familiare-mensile-come-farlo" class="text-accent hover:underline font-medium">budget familiare</a> conviene creare una categoria dedicata, così da vedere quanto costa davvero. Le voci cambiano con l''età:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Primo anno</strong>: pannolini, alimentazione, visite e farmaci, abbigliamento che va sostituito di frequente.</li><li><strong>Prima infanzia</strong>: asilo nido o baby-sitter, spesso la voce più pesante di tutte.</li><li><strong>Età scolare</strong>: materiale scolastico, mensa, attività sportive e corsi.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molte di queste spese sono ricorrenti: registrarle come tali aiuta a prevedere il loro peso mese per mese, mentre le spese annuali come l''iscrizione a scuola vanno accantonate in anticipo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I sostegni pubblici</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Esistono diversi aiuti per le famiglie con figli, come l''assegno unico universale, che varia in base all''ISEE, e contributi per la frequenza dell''asilo nido. Importi e requisiti cambiano spesso: conviene verificare le misure in vigore sul sito dell''INPS o presso un patronato, e presentare le domande per tempo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Pensare al futuro</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una volta assestato il bilancio, molte famiglie iniziano ad accantonare una piccola somma per il futuro del figlio, ad esempio per gli studi. Su orizzonti di quindici o vent''anni anche cifre modeste crescono in modo significativo grazie all''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>, ad esempio con un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È anche il momento di parlarne in coppia: chi paga cosa, come cambia la gestione dei conti, come proteggersi in caso di imprevisti. Ne parliamo nell''articolo sulle <a href="/news/finanze-di-coppia-conti-separati-o-cointestati" class="text-accent hover:underline font-medium">finanze di coppia</a>. Per fissare una cifra da raggiungere puoi usare il <a href="/calcolatore-obiettivo-risparmio.php" class="text-accent hover:underline font-medium">calcolatore obiettivo di risparmio</a>, e seguire le spese della famiglia su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a>.</p>',
    'pubblicato',
    '2026-09-10 09:00:00',
    '2026-09-10 09:00:00'
);
